#include "core/InstrumentBodyFilter.h"
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <limits>
#include <cstdint>
using cs80::body::InstrumentBodyFilter;
static double input(int i) { return .21 * std::sin(i * .137) + .07 * std::cos(i * .913); }
int main() {
 int failures=0; double peak=0; long samples=0; int cases=0;
 const double rates[]={8000,44100,48000,96000,192000,1536000,
     std::numeric_limits<double>::quiet_NaN(),std::numeric_limits<double>::infinity()};
 for(double rate:rates) {
  ++cases; InstrumentBodyFilter used, fresh; used.prepare(48000); fresh.prepare(rate);
  for(int i=0;i<523;++i) used.tick(float(input(i)),2100,1300,3.8f,4.0f,true,true);
  used.prepare(rate);
  int prepareMismatch=0;
  for(int i=0;i<1200;++i) {
   float x=float(input(i));
   float a=used.tick(x,2100,1300,3.8f,4.0f,i%211<100,i%317<200);
   float b=fresh.tick(x,2100,1300,3.8f,4.0f,i%211<100,i%317<200);
   prepareMismatch += a != b;
  }
  used.reset(); InstrumentBodyFilter resetReference; resetReference.prepare(rate); int resetMismatch=0;
  for(int i=0;i<1200;++i) {
   float a=used.tick(float(input(i)),500,1300,2.0f,4.0f,true,true);
   float b=resetReference.tick(float(input(i)),500,1300,2.0f,4.0f,true,true);
   resetMismatch += a != b;
  }
  // Snapshot at an off-boundary control sample, including a partially faded switch.
  used.tick(.1f,500,1300,2.0f,4.0f,false,true);
  auto outgoing=used, reference=used;
  int frozenMismatch=0;
  for(int i=0;i<4000;++i) {
   float x=float(input(i));
   float a=outgoing.tickFrozen(x);
   float b=reference.tick(x,500,1300,2.0f,4.0f,false,true);
   frozenMismatch += a != b;
   // Incoming filter receives unrelated live controls and must not alter snapshot.
   used.tick(x,10000,70,.5f,.5f,true,false);
  }
  InstrumentBodyFilter stress; stress.prepare(rate); int nonfinite=0;
  for(int i=0;i<50000;++i) {
   const bool phase=(i/16)%2;
   float hp=phase?1.0e9f:-100.f, lp=phase?-100.f:1.0e9f;
   if(i%1024<16) hp=std::numeric_limits<float>::quiet_NaN();
   const float q=i%2048<16?std::numeric_limits<float>::infinity():4.0f;
   float y=stress.tick(float(input(i)),hp,lp,q,q,i%73<40,i%101<60);
   nonfinite += !std::isfinite(y); peak=std::max(peak,std::abs(double(y))); ++samples;
  }
  stress.reset(); int resetResidue=0;
  for(int i=0;i<2048;++i) resetResidue += stress.tick(0,800,1300,4,4,true,true)!=0;
  failures += prepareMismatch+resetMismatch+frozenMismatch+nonfinite+resetResidue;
  std::printf("rate %.0f prepare_mismatch %d reset_mismatch %d frozen_mismatch %d nonfinite %d reset_residue %d\n",rate,prepareMismatch,resetMismatch,frozenMismatch,nonfinite,resetResidue);
 }
 std::printf("SUMMARY cases %d stress_samples %ld peak %.9g failures %d\n",cases,samples,peak,failures);
 return failures?1:0;
}
